        jne     .L161                       ; unsigned ==
; ---- lineNew()
        call    motext__lineNew
        jmp     .L162
.L161:
; ---- } else if ( ch != '\r' ) {
        mov     al, [textLoad__ch]
        cmp     al, 13                      ; byte operands, no widening
        je      .L164                       ; unsigned !=
; ---- lineAppend( lineCount - 1, ch )
        mov     ax, [motext__lineCount]
        dec     ax
        mov     [lineAppend__ln], ax
        mov     al, [textLoad__ch]
        mov     [lineAppend__ch], al        ; u8 -> u8, no widening
        call    lineAppend
.L164:
.L162:
; ---- undoing = false
        mov     byte [motext__undoing], 0
; ---- return
        ret
.L158:
; ---- if ( ch == '\r' ) return
        mov     al, [textLoad__ch]
        cmp     al, 13                      ; byte operands, no widening
        jne     .L167                       ; unsigned ==
        ret
.L167:
; ---- if ( ch == '\n' ) {
        mov     al, [textLoad__ch]
        cmp     al, 10                      ; byte operands, no widening
        jne     .L170                       ; unsigned ==
; ---- bulkFlush()
        call    motext__bulkFlush
; ---- lineNew()
        call    motext__lineNew
; ---- bulkSeed()
        call    motext__bulkSeed
; ---- return
        ret
.L170:
; ---- if ( loadUsed == chunkSize ) {
        mov     ax, [motext__loadUsed]
        cmp     ax, 16
        je      .L175                       ; unsigned ==
        jmp     .L173
.L175:
; ---- chunkUsed[loadChunk] = chunkSize
        mov     ax, [motext__loadChunk]
        mov     bx, ax
        mov     dx, [motext__usedSeg]       ; segment of motext__chunkUsed
        mov     es, dx
        mov     byte [es:bx], 16
; ---- d = chunkTake()
        call    motext__chunkTake
        mov     ax, [motext__chunkTake__ret]
        mov     [textLoad__d], ax
; ---- if ( d == 0 ) {
        test    ax, ax
        jne     .L176                       ; unsigned ==
; ---- noRoom = true
        mov     byte [motext__noRoom], 1
; ---- whyNoRoom = whyChunks
        mov     byte [motext__whyNoRoom], 1
; ---- return
        ret
.L176:
; ---- chunkNext[loadChunk] = d
        mov     ax, [textLoad__d]
        mov     bx, [motext__loadChunk]
        shl     bx, 1                       ; word elements
        mov     dx, [motext__nextSeg]       ; segment of motext__chunkNext
        mov     es, dx
        mov     [es:bx], ax
; ---- loadChunk = d
        mov     ax, [textLoad__d]
        mov     [motext__loadChunk], ax
; ---- loadUsed  = 0
        mov     word [motext__loadUsed], 0
; ---- atDst( loadChunk )
        mov     ax, [motext__loadChunk]
        mov     [motext__atDst__c], ax
        call    motext__atDst
.L173:
; ---- dst[loadUsed] = ch
        mov     al, [textLoad__ch]
        mov     bx, [motext__loadUsed]
        mov     dx, [motext__dstSeg]        ; segment of motext__dst
        mov     es, dx
        mov     [es:bx], al
; ---- loadUsed++
        inc     word [motext__loadUsed]
; ---- loadLen++
        inc     word [motext__loadLen]
        ret

; ============================================== sub viewSize ====

viewSize:
; ---- height = h
        mov     ax, [viewSize__h]
        mov     [moview__height], ax
; ---- width = w > viewMaxWidth ? viewMaxWidth : w
        mov     ax, [viewSize__w]
        cmp     ax, 160
        jbe     .L179                       ; unsigned >
        mov     ax, 160
        jmp     .L180
.L179:
        mov     ax, [viewSize__w]
.L180:
        mov     [moview__width], ax
        ret

; ============================================== sub viewHome ====

viewHome:
; ---- top = 0
        mov     word [moview__top], 0
; ---- left = 0
        mov     word [moview__left], 0
; ---- curLine = 0
        mov     word [moview__curLine], 0
; ---- curCol = 0
        mov     word [moview__curCol], 0
; ---- marked = false
        mov     byte [moview__marked], 0
        ret

; ============================================== u16 viewTop ====

viewTop:
; ---- u16 viewTop() => top
        mov     ax, [moview__top]
        mov     [viewTop__ret], ax
        ret

; ============================================== u16 viewLeft ====

viewLeft:
; ---- u16 viewLeft() => left
        mov     ax, [moview__left]
        mov     [viewLeft__ret], ax
        ret

; ============================================== u16 viewLine ====

viewLine:
; ---- u16 viewLine() => curLine
        mov     ax, [moview__curLine]
        mov     [viewLine__ret], ax
        ret

; ============================================== u16 viewCol ====

viewCol:
; ---- u16 viewCol() => curCol
        mov     ax, [moview__curCol]
        mov     [viewCol__ret], ax
        ret

; ============================================== sub moview__viewFollow ====

moview__viewFollow:
; ---- if ( curLine < top ) top = curLine
        mov     ax, [moview__curLine]
        mov     bx, [moview__top]
        cmp     ax, bx
        jae     .L182                       ; unsigned <
        mov     ax, [moview__curLine]
        mov     [moview__top], ax
.L182:
; ---- if ( curLine >= top + height ) top = curLine - height + 1
        mov     ax, [moview__curLine]
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [moview__top]
        mov     bx, [moview__height]
        add     ax, bx
        mov     bx, ax
        pop     ax
        cmp     ax, bx
        jb      .L185                       ; unsigned >=
        mov     ax, [moview__curLine]
        mov     bx, [moview__height]
        sub     ax, bx
        inc     ax
        mov     [moview__top], ax
.L185:
; ---- if ( curCol < left ) left = curCol
        mov     ax, [moview__curCol]
        mov     bx, [moview__left]
        cmp     ax, bx
        jae     .L188                       ; unsigned <
        mov     ax, [moview__curCol]
        mov     [moview__left], ax
.L188:
; ---- if ( curCol >= left + width ) left = curCol - width + 1
        mov     ax, [moview__curCol]
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [moview__left]
        mov     bx, [moview__width]
        add     ax, bx
        mov     bx, ax
        pop     ax
        cmp     ax, bx
        jb      .L191                       ; unsigned >=
        mov     ax, [moview__curCol]
        mov     bx, [moview__width]
        sub     ax, bx
        inc     ax
        mov     [moview__left], ax
.L191:
        ret

; ============================================== sub viewGoto ====

viewGoto:
; ---- goalCol = col
        mov     ax, [viewGoto__col]
        mov     [moview__goalCol], ax
; ---- viewPlace( ln, col )
        mov     ax, [viewGoto__ln]
        mov     [moview__viewPlace__ln], ax
        mov     ax, [viewGoto__col]
        mov     [moview__viewPlace__col], ax
        call    moview__viewPlace
        ret

; ============================================== sub viewGotoLine ====

viewGotoLine:
; ---- viewPlace( ln, goalCol )
        mov     ax, [viewGotoLine__ln]
        mov     [moview__viewPlace__ln], ax
        mov     ax, [moview__goalCol]
        mov     [moview__viewPlace__col], ax
        call    moview__viewPlace
        ret

; ============================================== sub moview__viewPlace ====

moview__viewPlace:
; ---- lines = textLines()
        call    textLines
        mov     ax, [textLines__ret]
        mov     [moview__viewPlace__lines], ax
; ---- curLine = ln
        mov     ax, [moview__viewPlace__ln]
        mov     [moview__curLine], ax
; ---- if ( lines > 0 && curLine >= lines ) curLine = lines - 1
        mov     ax, [moview__viewPlace__lines]
        test    ax, ax
        jbe     .L194                       ; unsigned >
        mov     ax, [moview__curLine]
        mov     bx, [moview__viewPlace__lines]
        cmp     ax, bx
        jb      .L194                       ; unsigned >=
        mov     ax, [moview__viewPlace__lines]
        dec     ax
        mov     [moview__curLine], ax
.L194:
; ---- curCol = col
        mov     ax, [moview__viewPlace__col]
        mov     [moview__curCol], ax
; ---- if ( curCol > lineLength( curLine ) ) curCol = lineLength( curLine )
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [moview__curLine]
        mov     [lineLength__ln], ax
        call    lineLength
        mov     ax, [lineLength__ret]
        mov     bx, ax
        pop     ax
        cmp     ax, bx
        jbe     .L198                       ; unsigned >
        mov     ax, [moview__curLine]
        mov     [lineLength__ln], ax
        call    lineLength
        mov     ax, [lineLength__ret]
        mov     [moview__curCol], ax
.L198:
; ---- viewFollow()
        call    moview__viewFollow
        ret

; ============================================== sub viewRender ====

viewRender:
; ---- for ( u16 y = 0; y < height; y++ ) {
        mov     word [viewRender__y], 0
.L201:
        mov     ax, [viewRender__y]
        mov     bx, [moview__height]
        cmp     ax, bx
        jb      .L204                       ; unsigned <
        jmp     .L203
.L204:
; ---- ln = top + y
        mov     ax, [moview__top]
        mov     bx, [viewRender__y]
        add     ax, bx
        mov     [viewRender__ln], ax
; ---- n = 0
        mov     word [viewRender__n], 0
; ---- if ( ln < textLines() ) n = lineSlice( ln, left, width, addr( row ) )
        mov     ax, [viewRender__ln]
        push    ax                          ; save lhs: rhs is not a leaf
        call    textLines
        mov     ax, [textLines__ret]
        mov     bx, ax
        pop     ax
        cmp     ax, bx
        jae     .L205                       ; unsigned <
        mov     ax, [viewRender__ln]
        mov     [lineSlice__ln], ax
        mov     ax, [moview__left]
        mov     [lineSlice__col], ax
        mov     ax, [moview__width]
        mov     [lineSlice__count], ax
