        mov     [viewRow__at], ax
        mov     ax, [viewRender__n]
        mov     [viewRow__n], ax
        call    viewRow
.L202:
        inc     word [viewRender__y]
        jmp     .L201
.L203:
        ret

; ============================================== sub viewRow ====

viewRow:
; ---- for ( u16 i = 0; i < n; i++ ) {
        mov     word [viewRow__i], 0
.L208:
        mov     ax, [viewRow__i]
        mov     bx, [viewRow__n]
        cmp     ax, bx
        jae     .L210                       ; unsigned <
