        mov     bx, [viewRow__i]
        add     ax, bx
        mov     bx, ax
        mov     al, [bx]                    ; peek8 - unchecked, by design
        mov     [putChar__c], al            ; u8 -> u8, no widening
        call    putChar
.L209:
        inc     word [viewRow__i]
        jmp     .L208
.L210:
; ---- putChar( '|' )
        mov     byte [putChar__c], 124
        call    putChar
; ---- newline()
        call    newline
        ret

; ============================================== sub showWhere ====

showWhere:
; ---- putNumber( viewTop() )
        call    viewTop
        mov     ax, [viewTop__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( viewLeft() )
        call    viewLeft
        mov     ax, [viewLeft__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
        ret

; ============================================== sub showAt ====

showAt:
; ---- putNumber( viewLine() )
        call    viewLine
        mov     ax, [viewLine__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( viewCol() )
        call    viewCol
        mov     ax, [viewCol__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

